{
  "name": "环形区域图形组件",
  "name_en": "Ring Region Graphic Component",
  "manufacturer": "Nion",
  "description": "一个非物理的软件图形组件，用于在科学图像或谱图界面中定义、编辑和序列化环形区域。它通常用于交互式选择环形 ROI、生成掩膜或支持测量与分析显示，而不是直接控制任何实验硬件。",
  "description_en": "A non-physical software graphic component used to define, edit, and serialize a ring-shaped region in scientific image or spectrum interfaces. It is typically used for interactive ring ROI selection, mask generation, and measurement/analysis display, rather than direct control of any laboratory hardware.",
  "actions": [
    {
      "action_name": "auto-radius_1",
      "description": "获取/设置环形区域的第一半径。",
      "description_en": "Get/set the first radius of the ring region."
    },
    {
      "action_name": "auto-radius_2",
      "description": "获取/设置环形区域的第二半径。",
      "description_en": "Get/set the second radius of the ring region."
    },
    {
      "action_name": "auto-mode",
      "description": "获取/设置环形图形的模式。",
      "description_en": "Get/set the mode of the ring graphic."
    },
    {
      "action_name": "auto-mime_data_dict",
      "description": "将环形图形状态导出为 MIME 数据字典。",
      "description_en": "Export the ring graphic state as a MIME data dictionary."
    },
    {
      "action_name": "auto-read_from_mime_data",
      "description": "从 MIME 数据字典读取并恢复环形图形状态。",
      "description_en": "Read and restore the ring graphic state from a MIME data dictionary."
    },
    {
      "action_name": "auto-test",
      "description": "在界面坐标中对指针位置执行环形图形命中测试。",
      "description_en": "Perform hit-testing of the ring graphic against a pointer position in widget coordinates."
    },
    {
      "action_name": "auto-begin_drag",
      "description": "开始对环形图形进行拖拽编辑。",
      "description_en": "Begin a drag interaction to edit the ring graphic."
    },
    {
      "action_name": "auto-end_drag",
      "description": "结束环形图形的拖拽编辑。",
      "description_en": "End the drag interaction for the ring graphic."
    },
    {
      "action_name": "auto-adjust_part",
      "description": "在拖拽过程中调整环形图形的选定部分。",
      "description_en": "Adjust the selected part of the ring graphic during dragging."
    },
    {
      "action_name": "auto-label_position",
      "description": "计算环形图形标签的显示位置。",
      "description_en": "Calculate the display position of the ring graphic label."
    }
  ],
  "tag_hints": [
    "ring ROI",
    "scientific image annotation",
    "mask generation",
    "interactive graphics",
    "hit testing",
    "ROI editing",
    "Nion Swift"
  ]
}

